<?php

namespace App\Filament\Bread;

use Illuminate\Database\Query\Builder;

class BreadTextPreviewSearch
{
    // Browse escapes the remaining b/i/u markup: keep it as searchable literal text.
    private const STRIP_RICH_TAGS = <<<'REGEXP'
(?si)<!--.*?-->|<\?.*?\?>|<![^>]*>|</?(?!(?:b|i|u)(?=[\s/>]))[a-z](?:"[^"]*"|'[^']*'|[^'">])*>
REGEXP;

    /** Match the literal 200-character caption generated by Voyager's browse view. */
    public function apply(Builder $query, string $column, string $type, array $details, bool $translated, string $term, string $operator): bool
    {
        if ($translated || isset($details['view']) || ! in_array($type, ['text', 'text_area', 'number', 'rich_text_box'], true)) {
            return false;
        }
        $driver = $query->getConnection()->getDriverName();
        $bindings = [];
        if ($driver === 'sqlite') {
            $text = 'CAST('.$column.' AS TEXT)';
            if ($type === 'rich_text_box') {
                $query->getConnection()->getPdo()->sqliteCreateFunction('viar_bread_strip_rich_tags',
                    static fn (?string $value): ?string => $value === null ? null : strip_tags($value, '<b><i><u>'), 1);
                $text = 'viar_bread_strip_rich_tags('.$text.')';
            }
            $caption = "CASE WHEN LENGTH($text) > 200 THEN SUBSTR($text, 1, 200) || ' ...' ELSE $text END";
        } elseif (in_array($driver, ['mysql', 'mariadb'], true)) {
            $text = 'CONVERT('.$column.' USING utf8mb4)';
            if ($type === 'rich_text_box') {
                $text = "REGEXP_REPLACE($text, CONVERT(? USING utf8mb4), '')";
                $bindings = array_fill(0, 3, self::STRIP_RICH_TAGS);
            }
            $caption = "CASE WHEN CHAR_LENGTH($text) > 200 THEN CONCAT(SUBSTRING($text, 1, 200), ' ...') ELSE $text END";
        } else {
            return false;
        }
        $value = $operator === '=' ? $term : app(BreadSmartSearch::class)->containsPattern($term);
        $query->orWhereRaw('('.$caption.') '.$operator.' ?'.($operator === '=' ? '' : " ESCAPE '!'"), [...$bindings, $value]);
        return true;
    }
}
